// Translation layer: TypeScript values in, verified Dafny model in the middle,
// TypeScript values out. model.cjs is generated by `mise run model`.
import { createRequire } from "node:module";
import type { Coupon, Item } from "../src/coupon";

const require = createRequire(import.meta.url);
const BigNumber = require("bignumber.js");
const { _dafny, CouponModel } = require("./model.cjs");

const big = (n: number) => new BigNumber(n);

// Dafny integers are unbounded and non-negative where the model says `nat`;
// callers must stay within safe, non-negative integers for prices and quantities.
export function modelApplyCoupon(items: Item[], coupon?: Coupon): number {
  const prices = _dafny.Seq.of(...items.map((i) => big(i.priceCents)));
  const quantities = _dafny.Seq.of(...items.map((i) => big(i.quantity)));
  const kind = !coupon ? 0 : coupon.kind === "percent" ? 1 : 2;
  const value = !coupon ? 0 : coupon.kind === "percent" ? coupon.percent : coupon.amountCents;
  const min = coupon?.minSubtotalCents ?? -1;
  return CouponModel.__default
    .Total(prices, quantities, big(kind), big(value), big(min))
    .toNumber();
}
